// GetSpec returns a spec by slug, body included. The canonical layout is
// .pose/specs/<slug>/spec.md or date-prefixed .pose/specs/<YYYY-MM-DD>-<slug>/spec.md;
// flat legacy/dated files (.pose/specs/<slug>.md, .pose/specs/<YYYY-MM-DD>-<slug>.md)
// and section-split directories are also supported.
func (s Store) GetSpec(slug string) (*Spec, error) {
	if err := ValidateSlug(slug); err != nil {
		return nil, err
	}
	var err error
	s, err = s.prepareReviewOperationRead()
	if err != nil {
		return nil, err
	}
	if sp, handled, err := s.reviewViewSpec(slug); handled {
		return sp, err
	}
	specs, err := s.ListSpecs("", "")
	if err != nil {
		return nil, err
	}
	var match *Spec
	for i := range specs {
		if specs[i].Slug != slug {
			continue
		}
		if match != nil {
			return nil, SpecIdentityConflictError{Slug: slug}
		}
		match = &specs[i]
	}
	if match == nil {
		return nil, fmt.Errorf("pose: spec %q not found", slug)
	}
	return s.readListedSpec(*match)
}

